static inline const uint8_t *font8x16_get(uint32_t cp) {
    size_t lo = 0;
    size_t hi = sizeof(font8x16_glyphs) / sizeof(font8x16_glyphs[0]);
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (font8x16_glyphs[mid].codepoint < cp) lo = mid + 1;
        else hi = mid;
    }
    if (lo < sizeof(font8x16_glyphs) / sizeof(font8x16_glyphs[0]) &&
        font8x16_glyphs[lo].codepoint == cp)
        return font8x16_glyphs[lo].rows;
    return (const uint8_t *)0;
}

